; Stops the game: removes the sprites, restores the screen and restarts at $800e. The demo starts again.
quit_to_demo
        lda #$00
        sta sprite_enable_shadow
        sta SPENA
        jsr hide_sprites_0_to_4         ; Stops the scripts and animations of sprites 0-4.
        jsr restore_work_bitmap
        jsr show_work_bitmap
        jsr reset_fight_colours         ; Clears the text area of the screen.
        lda sprite_mirror_state         ; Mirrors the fighter sprites back when they are mirrored.
        beq quit_to_demo_check_end
; not executed $94d8-$94de
        eor #$81
        sta sprite_mirror_state
        jsr mirror_shared_sprites
quit_to_demo_check_end
        lda final_stage                 ; Bit 7 of $bb: restores the screen areas of the end scene.
        bpl quit_to_demo_check_scene
        jsr swap_block_col13
        jsr swap_end_shapes
        lda final_goal_reached
        bpl quit_to_demo_check_scene
        jsr swap_block_col23
quit_to_demo_check_scene
        lda scene_index                 ; Goes back to scene 0 when scene 1 shows.
        beq quit_to_demo_restart
        jsr change_scene
quit_to_demo_restart
        sei                             ; Resets the stack and runs the warm start. The music setting stays.
        ldx #$ff
        txs
        jmp restart
